parameters.jsCode:
const input = JSON.parse($input.item.json.input || '{}');
const { application_type, date_of_birth, documents = [] } = input;

const issues = [];
const now = new Date();
const dob = new Date(date_of_birth);
const age = Math.floor((now - dob) / (1000 * 60 * 60 * 24 * 365.25));

// Age requirements
const ageRequirements = {
  'learners_permit': 16,
  'drivers_license': 18,
  'license_renewal': 18
};

const requiredAge = ageRequirements[application_type] || 18;
if (age < requiredAge) {
  issues.push(`Applicant is ${age} years old, minimum age is ${requiredAge}`);
}

// Document requirements by type
const docRequirements = {
  'learners_permit': ['photo', 'proof_of_age', 'medical_certificate'],
  'drivers_license': ['photo', 'proof_of_residence', 'medical_certificate'],
  'license_renewal': ['photo', 'medical_certificate']
};

const required = docRequirements[application_type] || [];
const submittedTypes = documents.map(d => d.type);
const verifiedTypes = documents.filter(d => d.verification_status === 'verified').map(d => d.type);

for (const req of required) {
  if (!submittedTypes.includes(req)) {
    issues.push(`Missing required document: ${req}`);
  } else if (!verifiedTypes.includes(req)) {
    issues.push(`Document not yet verified: ${req}`);
  }
}

const eligible = issues.length === 0;

return {
  eligible,
  age,
  required_age: requiredAge,
  documents_required: required,
  documents_submitted: submittedTypes,
  documents_verified: verifiedTypes,
  issues,
  recommendation: eligible ? 'approve' : (issues.some(i => i.includes('years old')) ? 'reject' : 'escalate')
};
